function unitPrice(price, qty){ if(!(qty>0)) return NaN; return price/qty; }
function bestValue(items){
  var bi=-1, bv=Infinity;
  for(var i=0;i<items.length;i++){
    var u=unitPrice(items[i].price, items[i].qty);
    if(!isNaN(u) && u<bv){ bv=u; bi=i; }
  }
  return bi;
}
function savings(items){
  var bi=bestValue(items);
  if(bi<0) return NaN;
  var best=unitPrice(items[bi].price, items[bi].qty);
  var maxU=-Infinity, maxI=-1;
  for(var i=0;i<items.length;i++){ var u=unitPrice(items[i].price,items[i].qty); if(!isNaN(u)&&u>maxU){maxU=u;maxI=i;} }
  return maxU-best;
}
var EXPORTS = { unitPrice:unitPrice, bestValue:bestValue, savings:savings };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.UnitPriceForgePure = EXPORTS; }
